class Solution:
    def insert(self, head, insertVal: int):
        node = Node(insertVal)
        if not head:
            node.next = node
            return node
        curr = head
        while True:
            if curr.val <= insertVal <= curr.next.val:
                break
            if curr.val > curr.next.val:
                if insertVal >= curr.val or insertVal <= curr.next.val:
                    break
            if curr.next == head:
                break
            curr = curr.next
        node.next = curr.next
        curr.next = node
        return head

